 lib/ftp.c | 2 +-
 1 file changed, 1 insertion(+), 1 deletion(-)
commit 9e3c35a88e9433fcc7edae4323605025f232f0bb
Author: Daniel Stenberg <daniel@haxx.se>
Date:   Mon Oct 6 09:54:39 2025 +0200

    ftp: fix the 213 scanner memchr buffer limit argument

    Reported-by: Joshua Rogers
    Closes #18867

diff --git a/lib/ftp.c b/lib/ftp.c
index a3194c2a7..10a61d368 100644
--- a/lib/ftp.c
+++ b/lib/ftp.c
@@ -2242,161 +2242,161 @@ static CURLcode ftp_state_retr(struct Curl_easy *data,
          is a part of the file left to get, although the server will just
          close the connection when we start the connection so it will not cause
          us any harm, just not make us exit as nicely. */
     }
     else {
       /* We got a file size report, so we check that there actually is a
          part of the file left to get, or else we go home.  */
       if(data->state.resume_from < 0) {
         /* We are supposed to download the last abs(from) bytes */
         if(filesize < -data->state.resume_from) {
           failf(data, "Offset (%" FMT_OFF_T
                 ") was beyond file size (%" FMT_OFF_T ")",
                 data->state.resume_from, filesize);
           return CURLE_BAD_DOWNLOAD_RESUME;
         }
         /* convert to size to download */
         ftp->downloadsize = -data->state.resume_from;
         /* download from where? */
         data->state.resume_from = filesize - ftp->downloadsize;
       }
       else {
         if(filesize < data->state.resume_from) {
           failf(data, "Offset (%" FMT_OFF_T
                 ") was beyond file size (%" FMT_OFF_T ")",
                 data->state.resume_from, filesize);
           return CURLE_BAD_DOWNLOAD_RESUME;
         }
         /* Now store the number of bytes we are expected to download */
         ftp->downloadsize = filesize-data->state.resume_from;
       }
     }

     if(ftp->downloadsize == 0) {
       /* no data to transfer */
       Curl_xfer_setup_nop(data);
       infof(data, "File already completely downloaded");

       /* Set ->transfer so that we will not get any error in ftp_done()
        * because we did not transfer the any file */
       ftp->transfer = PPTRANSFER_NONE;
       ftp_state(data, ftpc, FTP_STOP);
       return CURLE_OK;
     }

     /* Set resume file transfer offset */
     infof(data, "Instructs server to resume from offset %" FMT_OFF_T,
           data->state.resume_from);

     result = Curl_pp_sendf(data, &ftpc->pp, "REST %" FMT_OFF_T,
                            data->state.resume_from);
     if(!result)
       ftp_state(data, ftpc, FTP_RETR_REST);
   }
   else {
     /* no resume */
     result = Curl_pp_sendf(data, &ftpc->pp, "RETR %s", ftpc->file);
     if(!result)
       ftp_state(data, ftpc, FTP_RETR);
   }

   return result;
 }

 static CURLcode ftp_state_size_resp(struct Curl_easy *data,
                                     struct ftp_conn *ftpc,
                                     struct FTP *ftp,
                                     int ftpcode,
                                     ftpstate instate)
 {
   CURLcode result = CURLE_OK;
   curl_off_t filesize = -1;
   char *buf = curlx_dyn_ptr(&ftpc->pp.recvbuf);
   size_t len = ftpc->pp.nfinal;

   /* get the size from the ascii string: */
   if(ftpcode == 213) {
     /* To allow servers to prepend "rubbish" in the response string, we scan
        for all the digits at the end of the response and parse only those as a
        number. */
     char *start = &buf[4];
-    const char *fdigit = memchr(start, '\r', len);
+    const char *fdigit = memchr(start, '\r', len - 4);
     if(fdigit) {
       fdigit--;
       if(*fdigit == '\n')
         fdigit--;
       while(ISDIGIT(fdigit[-1]) && (fdigit > start))
         fdigit--;
     }
     else
       fdigit = start;
     if(curlx_str_number(&fdigit, &filesize, CURL_OFF_T_MAX))
       filesize = -1; /* size remain unknown */
   }
   else if(ftpcode == 550) { /* "No such file or directory" */
     /* allow a SIZE failure for (resumed) uploads, when probing what command
        to use */
     if(instate != FTP_STOR_SIZE) {
       failf(data, "The file does not exist");
       return CURLE_REMOTE_FILE_NOT_FOUND;
     }
   }

   if(instate == FTP_SIZE) {
 #ifdef CURL_FTP_HTTPSTYLE_HEAD
     if(filesize != -1) {
       char clbuf[128];
       int clbuflen = msnprintf(clbuf, sizeof(clbuf),
                 "Content-Length: %" FMT_OFF_T "\r\n", filesize);
       result = client_write_header(data, clbuf, clbuflen);
       if(result)
         return result;
     }
 #endif
     Curl_pgrsSetDownloadSize(data, filesize);
     result = ftp_state_rest(data, ftpc, ftp);
   }
   else if(instate == FTP_RETR_SIZE) {
     Curl_pgrsSetDownloadSize(data, filesize);
     result = ftp_state_retr(data, ftpc, ftp, filesize);
   }
   else if(instate == FTP_STOR_SIZE) {
     data->state.resume_from = filesize;
     result = ftp_state_ul_setup(data, ftpc, ftp, TRUE);
   }

   return result;
 }

 static CURLcode ftp_state_rest_resp(struct Curl_easy *data,
                                     struct ftp_conn *ftpc,
                                     struct FTP *ftp,
                                     int ftpcode,
                                     ftpstate instate)
 {
   CURLcode result = CURLE_OK;

   switch(instate) {
   case FTP_REST:
   default:
 #ifdef CURL_FTP_HTTPSTYLE_HEAD
     if(ftpcode == 350) {
       char buffer[24]= { "Accept-ranges: bytes\r\n" };
       result = client_write_header(data, buffer, strlen(buffer));
       if(result)
         return result;
     }
 #endif
     result = ftp_state_prepare_transfer(data, ftpc, ftp);
     break;

   case FTP_RETR_REST:
     if(ftpcode != 350) {
       failf(data, "Couldn't use REST");
       result = CURLE_FTP_COULDNT_USE_REST;
     }
     else {
       result = Curl_pp_sendf(data, &ftpc->pp, "RETR %s", ftpc->file);
       if(!result)
         ftp_state(data, ftpc, FTP_RETR);
     }
     break;
